[
    {
        "title": "客户集中度高的影响",
        "value": "前五大客户合计销售额占总收入比例在2016至2019年期间持续上升，从2016年的11.87%增至2019年的89.72%。",
        "evidence": "发行人报告期内向前五名客户合计销售额分别为 4,189.49 万元、10,208.22 万元、16,014.91 万元和 4,401.33 万元，占营业收入的比重分别为 52.66%、68.58%、80.83%和 89.72%。",
        "type": "table_summary"
    },
    {
        "title": "军种客户收入占比",
        "value": "2019年1-6月，军种客户收入占比8.62%，为各军种中最高；2018年，军种二客户收入占比最高，为13.23%。",
        "evidence": "2019年1-6月军种一至四占比分别为0.38%、0.60%、8.62%、5.76%；2018年军种一至四占比分别为41.30%、0.21%、13.23%、8.29%。",
        "type": "table_fact"
    },
    {
        "title": "军种客户收入金额",
        "value": "2019年1-6月，军种三客户收入金额最高，为422.55万元；2018年，军种二客户收入金额最高，为2,619.38万元。",
        "evidence": "2019年1-6月军种一至四金额分别为18.77、29.47、422.55、282.59万元；2018年军种一至四金额分别为8,178.03、41.10、2,619.38、1,641.76万元。",
        "type": "table_fact"
    }
]

